export type Lesson = {
  id: string
  courseSlug: string
  title: string
  duration: string
  summary: string
  explanation: string
  language: string
  code: string
  exercise: string
  question: string
  choices: string[]
  answer: number
  answerNote: string
}

type LessonSeed = Omit<Lesson, 'id' | 'courseSlug'>
const lesson = (courseSlug: string, index: number, data: LessonSeed): Lesson => ({ ...data, id: `${courseSlug}-${index}`, courseSlug })

const lessonSeeds: Lesson[] = [
  lesson('html-fundamentals', 1, { title: 'A document with meaning', duration: '25 min', summary: 'Give a web page a useful, readable structure.', explanation: 'HTML describes the meaning and structure of content. Begin with a doctype, a head for metadata, and a body for what people read. Choose elements for their meaning rather than their default appearance.', language: 'html', code: '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <title>Field Notes</title>\n  </head>\n  <body>\n    <main>\n      <h1>Field Notes</h1>\n      <p>Ideas from the trail.</p>\n    </main>\n  </body>\n</html>', exercise: 'Create a document with a descriptive title, one main landmark, a heading, and a short paragraph.', question: 'Where does visible page content belong?', choices: ['Inside head', 'Inside body', 'Inside the doctype'], answer: 1, answerNote: 'The body contains document content rendered on the page.' }),
  lesson('html-fundamentals', 2, { title: 'Headings, landmarks & flow', duration: '35 min', summary: 'Build a page outline that works for people and assistive technology.', explanation: 'Use one clear h1 for the page topic and nest subsequent headings logically. Landmarks such as header, nav, main, and footer make pages easier to navigate and understand.', language: 'html', code: '<header><a href="/">Northstar</a></header>\n<nav aria-label="Main">...</nav>\n<main>\n  <h1>Trail journal</h1>\n  <section aria-labelledby="recent">\n    <h2 id="recent">Recent entries</h2>\n    <article><h3>Along the coast</h3></article>\n  </section>\n</main>\n<footer>Made with care.</footer>', exercise: 'Add a navigation landmark and two sections under the page h1. Give each section a descriptive heading.', question: 'Which heading identifies the overall page topic?', choices: ['The h1', 'The first h4', 'A bold paragraph'], answer: 0, answerNote: 'A clear h1 identifies the main topic, followed by nested section headings.' }),
  lesson('html-fundamentals', 3, { title: 'Links, media & accessible forms', duration: '45 min', summary: 'Connect pages and label inputs so they are usable.', explanation: 'Links describe destinations; buttons perform actions. Informative images need alternative text. Form controls need visible labels associated by matching for and id attributes, not placeholder text alone.', language: 'html', code: '<a href="/journal">Read the journal</a>\n<img src="coast.jpg" alt="Rocky coastline at sunrise">\n<label for="email">Email address</label>\n<input id="email" name="email" type="email">\n<button type="submit">Subscribe</button>', exercise: 'Add a meaningful link, informative image alternative, and labeled email input.', question: 'What makes an input label accessible?', choices: ['A placeholder only', 'A label associated with the input id', 'A nearby unassociated heading'], answer: 1, answerNote: 'An associated label programmatically names the form control.' }),
  lesson('css-responsive-design', 1, { title: 'Selectors & the cascade', duration: '40 min', summary: 'Understand how style rules target elements and resolve conflicts.', explanation: 'A CSS rule combines a selector and declarations. The cascade considers origin, importance, specificity, and source order. Focused selectors make styles easier to maintain.', language: 'css', code: '.notice {\n  color: #f4f2fb;\n  background: #222536;\n  padding: 1rem;\n}\n.notice strong { color: #a895ff; }', exercise: 'Create a .card rule with padding and a border, then style only its heading.', question: 'When specificity ties, which declaration normally wins?', choices: ['The earlier rule', 'The later rule in source order', 'The shortest selector'], answer: 1, answerNote: 'With equal cascade priority and specificity, later source order wins.' }),
  lesson('css-responsive-design', 2, { title: 'Layout with Flexbox and Grid', duration: '55 min', summary: 'Choose layout tools that match the shape of your content.', explanation: 'Flexbox lays items along a primary axis and suits toolbars and aligned groups. Grid handles rows and columns together and suits page regions or card collections. Both adapt without fixed positioning.', language: 'css', code: '.toolbar { display: flex; align-items: center; justify-content: space-between; }\n\n.course-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));\n  gap: 1rem;\n}', exercise: 'Make a card grid that collapses naturally when there is not enough space.', question: 'Which layout is designed for rows and columns together?', choices: ['CSS Grid', 'Inline flow', 'Text decoration'], answer: 0, answerNote: 'Grid manages both dimensions of a layout.' }),
  lesson('css-responsive-design', 3, { title: 'Responsive design & accessible polish', duration: '50 min', summary: 'Adapt interfaces to screens, preferences, and input methods.', explanation: 'Start with content that flows naturally, then add breakpoints when the layout needs them. Use relative sizing, visible focus, and respect reduced-motion preferences. Responsive design includes zoom and input needs too.', language: 'css', code: '.page { width: min(100% - 2rem, 72rem); margin-inline: auto; }\n@media (max-width: 42rem) { .toolbar { flex-direction: column; } }\n@media (prefers-reduced-motion: reduce) { * { scroll-behavior: auto; } }', exercise: 'Add a narrow-screen layout change and a reduced-motion rule to a sample page.', question: 'When should you add a breakpoint?', choices: ['At every common device width', 'When the content or layout needs it', 'Only at exactly 768px'], answer: 1, answerNote: 'Content-driven breakpoints work across real screen sizes.' }),
  lesson('javascript-fundamentals', 1, { title: 'Values, variables & types', duration: '45 min', summary: 'Store information and choose clear, dependable value types.', explanation: 'Use const by default for bindings you do not reassign, and let when you do. Strings, numbers, booleans, arrays, objects, null, and undefined represent different data. Descriptive names communicate intent.', language: 'javascript', code: 'const learner = { name: "Ari", lessonsComplete: 2, isLearning: true };\nconst greeting = "Welcome, " + learner.name;\nconsole.log(greeting);', exercise: 'Create an object describing a project with a title, technologies array, and published Boolean.', question: 'Which declaration fits a value you will not reassign?', choices: ['const', 'var', 'global'], answer: 0, answerNote: 'const prevents reassignment and makes intent clearer.' }),
  lesson('javascript-fundamentals', 2, { title: 'Functions, arrays & decisions', duration: '55 min', summary: 'Break work into reusable steps and transform collections.', explanation: 'Functions accept inputs and can return results. Array methods such as map and filter make transformations explicit. Use conditionals to handle different cases clearly.', language: 'javascript', code: 'const minutes = [12, 25, 8, 40];\nfunction longerThan(limit) {\n  return minutes.filter((time) => time > limit);\n}\nconsole.log(longerThan(15)); // [25, 40]', exercise: 'Write a function that returns lesson durations of 30 minutes or more.', question: 'What does filter return?', choices: ['A new array of matching items', 'The first matching item only', 'A sorted original array'], answer: 0, answerNote: 'filter creates a new array of items that pass its condition.' }),
  lesson('javascript-fundamentals', 3, { title: 'Events & the browser DOM', duration: '60 min', summary: 'Respond to an action and update visible page content.', explanation: 'The DOM represents a document as objects. Select elements, attach event listeners, and update text or classes in response. Use textContent for user-provided text rather than injecting it as HTML.', language: 'javascript', code: 'const button = document.querySelector("#add-note");\nconst list = document.querySelector("#notes");\nbutton.addEventListener("click", () => {\n  const item = document.createElement("li");\n  item.textContent = "A new idea";\n  list.append(item);\n});', exercise: 'Add a button that appends a new list item each time it is clicked.', question: 'Which property safely inserts plain text?', choices: ['innerHTML', 'textContent', 'outerHTML'], answer: 1, answerNote: 'textContent treats the value as text, not parsed markup.' }),
  lesson('git-github', 1, { title: 'Your first repository', duration: '30 min', summary: 'Start tracking changes with clear, repeatable Git commands.', explanation: 'A repository contains your project and its history. git init starts local tracking, git status shows changes, and git add stages selected files for the next snapshot. A .gitignore excludes generated files and secrets.', language: 'bash', code: 'git init\ngit status\ngit add index.html styles.css\ngit commit -m "Create page structure"', exercise: 'Initialize a repository, create a README, stage it, and commit with a descriptive message.', question: 'What does git add do?', choices: ['Publishes files to the internet', 'Stages changes for a commit', 'Deletes project history'], answer: 1, answerNote: 'git add places selected changes in the staging area.' }),
  lesson('git-github', 2, { title: 'Branches, commits & collaboration', duration: '40 min', summary: 'Make focused changes and integrate them with a shared project.', explanation: 'Commits are snapshots. Branches let you work on focused changes without disturbing the default branch. Push sends commits to a remote; pull brings remote changes into local work. Pull requests invite review.', language: 'bash', code: 'git switch -c add-contact-page\n# make and test changes\ngit add .\ngit commit -m "Add contact page"\ngit push -u origin add-contact-page', exercise: 'Create a feature branch, make a small change, commit it, and describe a review request.', question: 'Why work on a feature branch?', choices: ['To isolate a change while it is developed', 'To remove commits', 'To make a repository private'], answer: 0, answerNote: 'Branches isolate work and make review and integration safer.' }),
  lesson('git-github', 3, { title: 'Remote repositories & safe workflow', duration: '35 min', summary: 'Sync hosted copies and protect sensitive information.', explanation: 'A remote hosts a copy of your repository. Keep a clear README, commit focused changes, and review diffs before pushing. Never commit API keys or credentials; rotate any secret that is exposed.', language: 'bash', code: 'git remote add origin https://github.com/you/project.git\ngit push -u origin main\ngit pull --rebase origin main\ngit log --oneline -5', exercise: 'Write setup steps in a README and ignore dependencies and local environment files.', question: 'What should you do if an API key is committed?', choices: ['Leave it if the repo is private', 'Revoke or rotate it immediately', 'Rename the variable'], answer: 1, answerNote: 'Treat exposed credentials as compromised and rotate them.' }),
  lesson('react-development', 1, { title: 'Components & props', duration: '50 min', summary: 'Describe interface pieces as reusable components.', explanation: 'A React component is a function that returns UI. Props pass information from a parent to a child. Keep components focused and use semantic HTML for their structure and controls.', language: 'jsx', code: 'function LessonCard({ title, minutes }) {\n  return (\n    <article>\n      <h2>{title}</h2>\n      <p>{minutes} minutes</p>\n    </article>\n  );\n}', exercise: 'Create a CourseBadge component that accepts title and difficulty props.', question: 'How should a child receive data from its parent?', choices: ['Through props', 'By changing the parent function', 'Through querySelector'], answer: 0, answerNote: 'Props are the standard way to pass data into a component.' }),
  lesson('react-development', 2, { title: 'State & user interactions', duration: '60 min', summary: 'Keep interactive UI synchronized with application state.', explanation: 'State represents information that changes over time. useState returns a value and setter; calling the setter schedules a render. Do not mutate arrays or objects in state directly.', language: 'jsx', code: 'function Counter() {\n  const [count, setCount] = useState(0);\n  return <button onClick={() => setCount((value) => value + 1)}>\n    Added {count} times\n  </button>;\n}', exercise: 'Build a toggle button whose label and aria-pressed value reflect its state.', question: 'How should state derive from its previous value?', choices: ['Mutate state directly', 'Use the setter with an updater function', 'Change DOM text manually'], answer: 1, answerNote: 'An updater function derives the next state from the previous value.' }),
  lesson('react-development', 3, { title: 'Effects, forms & composition', duration: '65 min', summary: 'Coordinate with browser systems and compose larger experiences.', explanation: 'Effects synchronize with systems outside React, such as subscriptions or browser APIs. Do not use effects for values calculable during render. Controlled fields keep their values in state and expose changes through events.', language: 'jsx', code: 'function SearchBox({ onSearch }) {\n  const [query, setQuery] = useState("");\n  function submit(event) {\n    event.preventDefault();\n    onSearch(query.trim());\n  }\n  return <form onSubmit={submit}>...</form>;\n}', exercise: 'Create a controlled form field with a label and submit its trimmed value without page reload.', question: 'What is an effect primarily for?', choices: ['Synchronizing with an external system', 'Calculating a value from props', 'Replacing composition'], answer: 0, answerNote: 'Effects are for synchronization with external systems.' }),
  lesson('apis-fetch', 1, { title: 'HTTP, endpoints & JSON', duration: '40 min', summary: 'Understand how a browser requests structured data.', explanation: 'An API exposes endpoints clients can request. HTTP methods communicate intent, status codes describe outcomes, and JSON is common data format. Check response status: fetch does not reject for HTTP errors.', language: 'javascript', code: 'const response = await fetch("/api/articles");\nif (!response.ok) {\n  throw new Error("Request failed: " + response.status);\n}\nconst articles = await response.json();', exercise: 'Fetch a public JSON endpoint, check response.ok, then parse the response body.', question: 'Does fetch reject automatically for HTTP 404?', choices: ['Yes, every non-2xx response rejects', 'No, check response.ok or status', 'Only for JSON'], answer: 1, answerNote: 'HTTP error statuses still produce a Response object.' }),
  lesson('apis-fetch', 2, { title: 'Async states & error handling', duration: '45 min', summary: 'Design loading, success, empty, and failure states.', explanation: 'Network requests can take time or fail. Represent loading, data, and error states explicitly. Give people useful feedback and let them retry operations when it is safe.', language: 'javascript', code: 'async function loadLessons() {\n  setStatus("loading");\n  try {\n    const response = await fetch("/api/lessons");\n    if (!response.ok) throw new Error("Could not load lessons");\n    setLessons(await response.json());\n    setStatus("success");\n  } catch (error) { setStatus("error"); }\n}', exercise: 'Sketch distinct loading, empty, and error messages for a fetched list.', question: 'Which states should a data view consider?', choices: ['Only success', 'Loading, success/empty, and failure', 'Only loading and failure'], answer: 1, answerNote: 'Explicit states tell users what happened and what the app is doing.' }),
  lesson('apis-fetch', 3, { title: 'Render remote data safely', duration: '50 min', summary: 'Turn API results into an accessible and resilient interface.', explanation: 'Validate data shape, use stable identifiers as keys, and render text as text. Never put private API credentials in browser code; client bundles are visible to visitors.', language: 'jsx', code: 'function ArticleList({ articles }) {\n  if (!articles.length) return <p>No articles yet.</p>;\n  return <ul>{articles.map((article) => (\n    <li key={article.id}><a href={article.url}>{article.title}</a></li>\n  ))}</ul>;\n}', exercise: 'Render API results with a stable key and an empty state.', question: 'Why use a stable id as a React key?', choices: ['It helps React track items between renders', 'It encrypts the content', 'It sorts the list'], answer: 0, answerNote: 'Stable keys help React match list items across updates.' }),
  lesson('website-deployment', 1, { title: 'Prepare a production build', duration: '35 min', summary: 'Create and inspect optimized files before publishing.', explanation: 'A production build transforms source into static assets a host can serve. Run it locally, inspect warnings, and verify generated output with a preview server before launch.', language: 'bash', code: 'npm run build\nnpm run preview\n# Test links, forms, and assets in the preview', exercise: 'Build your project and test its production preview, not only the development server.', question: 'Why preview a production build?', choices: ['To check production output', 'To install dependencies', 'To replace source control'], answer: 0, answerNote: 'Previewing catches issues that may not appear during development.' }),
  lesson('website-deployment', 2, { title: 'Static hosting & deployment', duration: '40 min', summary: 'Publish your site and configure client-side route fallback.', explanation: 'Static hosts serve built files from a CDN. A client-side router needs the host to send route requests back to the app entry point or direct nested URLs may return 404.', language: 'text', code: 'Build command: npm run build\nOutput directory: dist\n\nConfigure unknown paths to serve /index.html.', exercise: 'Publish a small site and open both its homepage and a nested route directly.', question: 'What helps a client-side route load on a static host?', choices: ['Fallback rewrite to the app entry point', 'Remove all route paths', 'Use larger images'], answer: 0, answerNote: 'The fallback lets the client router handle direct nested URL requests.' }),
  lesson('website-deployment', 3, { title: 'Domains, HTTPS & launch checks', duration: '35 min', summary: 'Finish public details and test a release responsibly.', explanation: 'Use HTTPS, connect a domain, and verify metadata, responsive layouts, and keyboard interaction. Keep dependencies updated and do not expose private credentials or learner data.', language: 'text', code: 'Launch checklist\n[ ] HTTPS enabled\n[ ] Direct route loading works\n[ ] Mobile layout checked\n[ ] Keyboard focus visible\n[ ] No private keys in client assets', exercise: 'Review your site on phone and desktop viewports using the checklist.', question: 'Which secret belongs in a frontend bundle?', choices: ['A private service credential', 'No private credentials', 'An obfuscated password'], answer: 1, answerNote: 'Anything in a browser bundle is visible; keep private credentials server-side.' }),
  lesson('html-fundamentals', 4, { title: 'Lists, tables & content relationships', duration: '35 min', summary: 'Represent grouped information with the right HTML elements.', explanation: 'HTML lists express relationships between related items. Use ul when order does not matter, ol when sequence matters, and li for each item. Tables are for genuinely tabular data where row and column headers describe relationships; they are not a general-purpose page layout tool. Semantic choices make the content easier to navigate and style.', language: 'html', code: '<ul aria-label="Tools I use">\n  <li>Browser devtools</li>\n  <li>Code editor</li>\n</ul>\n\n<table>\n  <caption>Workshop schedule</caption>\n  <thead><tr><th scope="col">Session</th><th scope="col">Time</th></tr></thead>\n  <tbody><tr><th scope="row">HTML</th><td>09:00</td></tr></tbody>\n</table>', exercise: 'Create an ordered three-step list and a small data table with a caption and scoped headers.', question: 'When is a table the right element?', choices: ['For aligning any page layout', 'For data with row or column relationships', 'Whenever content needs borders'], answer: 1, answerNote: 'Tables communicate relationships in tabular data, not visual page layout.' }),
  lesson('html-fundamentals', 5, { title: 'Forms, labels & browser validation', duration: '40 min', summary: 'Collect input with controls people can understand and use.', explanation: 'A form groups controls for submitting information. Each input needs a persistent accessible name, usually a label associated through matching for and id values. The name attribute is the key sent with a submitted value. Native types such as email and number provide useful input behavior, while required and min-length constraints can catch simple mistakes before submission.', language: 'html', code: '<form action="/signup" method="post">\n  <label for="email">Email address</label>\n  <input id="email" name="email" type="email" required>\n  <label for="topic">What do you want to learn?</label>\n  <select id="topic" name="topic">\n    <option value="html">HTML</option>\n    <option value="css">CSS</option>\n  </select>\n  <button type="submit">Join the list</button>\n</form>', exercise: 'Build a labeled sign-up form with an email input, one select field, and a submit button.', question: 'Which attribute name is used when the control value is submitted?', choices: ['name', 'placeholder', 'class'], answer: 0, answerNote: 'The name identifies the submitted form value.' }),
  lesson('html-fundamentals', 6, { title: 'Metadata, paths & a complete page', duration: '45 min', summary: 'Connect page content, assets, and search-friendly metadata.', explanation: 'Metadata is information about a document, rather than its main visible content. A useful title appears in browser tabs and search results, while a description can summarize the page. Relative paths resolve from the current document or stylesheet; an incorrect path is a common reason images and linked pages fail after publishing. Finish by checking the document with an HTML validator and by opening every link.', language: 'html', code: '<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Notes from local trail walks.">\n  <title>Trail Notes | Field Journal</title>\n</head>\n<body>\n  <main><h1>Trail Notes</h1><img src="images/coast.jpg" alt="Coast at sunrise"></main>\n</body>', exercise: 'Complete a small page with a title, description, viewport setting, meaningful image alternative, and working relative link.', question: 'What does a relative asset path depend on?', choices: ['The current document or stylesheet location', 'The screen width', 'The browser history length'], answer: 0, answerNote: 'A relative path is resolved from the file that references it.' }),
  lesson('css-responsive-design', 4, { title: 'The box model & sizing', duration: '50 min', summary: 'Understand the space every element occupies in a layout.', explanation: 'Every rendered element has a box made of content, padding, border, and margin. With the default content-box sizing, the declared width measures only the content, so padding and borders make the rendered box wider. The border-box model includes padding and borders in the declared width and is easier to reason about for most interface work. Normal document flow places content in reading order until a layout mode changes that behavior.', language: 'css', code: '*, *::before, *::after {\n  box-sizing: border-box;\n}\n\n.panel {\n  width: min(100%, 34rem);\n  padding: 1.5rem;\n  border: 1px solid #45485a;\n  margin-inline: auto;\n}', exercise: 'Apply border-box sizing and create a centered panel that never exceeds the available width.', question: 'With border-box sizing, what does width include?', choices: ['Content only', 'Content, padding, and border', 'Margin only'], answer: 1, answerNote: 'The border-box width includes content, padding, and border.' }),
  lesson('css-responsive-design', 5, { title: 'Type, color & reusable tokens', duration: '55 min', summary: 'Create a consistent visual system with readable defaults.', explanation: 'Typography controls how text looks and how comfortably it can be read. Choose a type scale with clear heading levels, readable body size, and enough line height. Color should communicate hierarchy while maintaining sufficient contrast between text and its background. CSS custom properties, often called design tokens, give repeated values names so one deliberate change can update an entire interface.', language: 'css', code: ':root {\n  --color-ink: #20212a;\n  --color-accent: #5366c9;\n  --space-card: 1.25rem;\n}\nbody { color: var(--color-ink); line-height: 1.6; }\nh1 { font-size: 2.25rem; line-height: 1.15; }\n.card { padding: var(--space-card); }', exercise: 'Define three custom properties for text color, accent color, and spacing, then use them in two component rules.', question: 'Why use a custom property for a repeated color?', choices: ['It makes the value reusable and centrally adjustable', 'It automatically checks contrast', 'It changes HTML semantics'], answer: 0, answerNote: 'A named token helps maintain and update repeated design values.' }),
  lesson('css-responsive-design', 6, { title: 'Interaction states & motion', duration: '45 min', summary: 'Give controls clear hover, focus, and reduced-motion behavior.', explanation: 'Interactive controls need visible states so people can tell when they are hovered, focused, pressed, or disabled. Keyboard focus is especially important for people who navigate without a pointer; never remove the browser outline without providing an equally visible replacement. Small transitions can explain a state change, but continuous or large movement can distract or cause discomfort. Respect the prefers-reduced-motion media feature.', language: 'css', code: 'button {\n  color: white;\n  background: #4355b5;\n  transition: background-color 160ms ease;\n}\nbutton:hover { background: #334493; }\nbutton:focus-visible { outline: 3px solid #a8b5ff; outline-offset: 3px; }\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { scroll-behavior: auto; transition-duration: 0.01ms; }\n}', exercise: 'Style hover and keyboard focus states for a button, then disable its transition for reduced-motion users.', question: 'Which selector targets keyboard focus without requiring pointer hover?', choices: [':focus-visible', ':hover', ':visited'], answer: 0, answerNote: ':focus-visible highlights focus when the browser determines it should be visible.' }),
  lesson('javascript-fundamentals', 4, { title: 'Objects, arrays & data transformations', duration: '55 min', summary: 'Model related data and produce new values from collections.', explanation: 'Objects group named properties that describe one thing; arrays hold ordered collections of values. Together they are common shapes for application data, such as a list of lesson records. map transforms each array item into a new result, filter keeps only matching items, and find returns the first match. These methods return new values, making changes easier to predict than mutating shared data.', language: 'javascript', code: 'const lessons = [\n  { title: "HTML basics", minutes: 25, complete: true },\n  { title: "CSS layout", minutes: 40, complete: false },\n];\nconst remainingTitles = lessons\n  .filter((item) => !item.complete)\n  .map((item) => item.title);\nconsole.log(remainingTitles);', exercise: 'Use filter and map to produce the titles of only the incomplete lessons in a sample array.', question: 'What does map return?', choices: ['A new array of transformed items', 'The first matching item', 'A Boolean'], answer: 0, answerNote: 'map returns a new array with each element transformed.' }),
  lesson('javascript-fundamentals', 5, { title: 'Scope, errors & debugging', duration: '50 min', summary: 'Find problems methodically and keep values close to where they are used.', explanation: 'Scope describes where a name is available in a program. Block-scoped const and let variables are limited to the block where they are declared, which helps prevent accidental collisions. Errors are useful signals: read the message and stack location, reproduce the problem, and inspect relevant values with browser developer tools. Fix the cause rather than hiding an error with a broad catch that provides no feedback.', language: 'javascript', code: 'function calculateAverage(scores) {\n  if (scores.length === 0) {\n    return 0;\n  }\n  const total = scores.reduce((sum, score) => sum + score, 0);\n  return total / scores.length;\n}\nconsole.log(calculateAverage([80, 90]));', exercise: 'Add a guard for an empty input array and use a breakpoint or console output to inspect an unexpected result.', question: 'What is a productive first response to a reproducible error?', choices: ['Read the error and inspect the failing values', 'Delete the code without investigating', 'Suppress all console messages'], answer: 0, answerNote: 'The error and current values help isolate the root cause.' }),
  lesson('javascript-fundamentals', 6, { title: 'Forms, storage & browser data', duration: '55 min', summary: 'Handle user input and keep small preferences across visits.', explanation: 'A form submit event represents a user request to send input. Read values from form controls, validate them, and show useful feedback instead of assuming input is correct. localStorage stores string key-value pairs in one browser, which is convenient for non-sensitive preferences. It is not a database, does not synchronize between devices, and must not hold secrets or sensitive personal information.', language: 'javascript', code: 'const form = document.querySelector("#name-form");\nconst input = document.querySelector("#name");\nform.addEventListener("submit", (event) => {\n  event.preventDefault();\n  const name = input.value.trim();\n  if (!name) return;\n  localStorage.setItem("learner-name", name);\n});', exercise: 'Prevent an empty name from being saved, then load and display the saved preference on a later visit.', question: 'Which statement about localStorage is accurate?', choices: ['It syncs securely across every device', 'It stores string values in the current browser', 'It is suitable for private passwords'], answer: 1, answerNote: 'localStorage is browser-local storage for string key-value pairs, not a secure account database.' }),
  lesson('git-github', 4, { title: 'Inspect history & undo safely', duration: '45 min', summary: 'Review changes before choosing an appropriate undo operation.', explanation: 'Git history is a sequence of commits linked together. git log shows past snapshots, while git diff compares working changes with staged or committed versions. Before undoing anything, inspect status and the diff so you know which work is affected. For a local edit that is not committed, git restore can discard selected working-tree changes; this is destructive, so use it only when you are certain.', language: 'bash', code: 'git status\ngit diff\ngit diff --staged\ngit log --oneline --decorate -8\n# To undo one uncommitted file after reviewing it:\ngit restore -- path/to/file', exercise: 'Create two commits, inspect their history and diff, then explain which changes are safe to restore.', question: 'What should you do before running a destructive undo command?', choices: ['Inspect status and the affected diff', 'Delete the repository folder', 'Push every file first'], answer: 0, answerNote: 'Reviewing status and diff helps avoid losing wanted changes.' }),
  lesson('git-github', 5, { title: 'Merge branches & resolve conflicts', duration: '50 min', summary: 'Bring independent work together and understand merge conflicts.', explanation: 'Merging combines the history of one branch into another. Git can combine separate edits automatically, but it pauses when two branches changed the same region in incompatible ways. Conflict markers identify the competing text; they are instructions for you, not valid final source code. Choose the intended result, remove markers, run relevant checks, then stage and commit the resolution.', language: 'bash', code: 'git switch main\ngit pull origin main\ngit merge add-contact-page\n# edit files with conflict markers, then verify\ngit diff\ngit add src/contact.html\ngit commit -m "Merge contact page"', exercise: 'Create conflicting edits on two branches in a practice repository, resolve them, and run a check before committing.', question: 'What does a conflict marker mean?', choices: ['Git needs you to choose the combined content', 'The project was deleted', 'The merge already passed every test'], answer: 0, answerNote: 'A conflict signals overlapping edits that Git cannot safely choose automatically.' }),
  lesson('git-github', 6, { title: 'Pull requests, review & releases', duration: '45 min', summary: 'Share work for review and make changes easy to understand.', explanation: 'A pull request proposes merging a branch into another and gives reviewers a focused place to inspect code, discuss trade-offs, and see automated checks. Keep requests small, explain why the change exists, and mention how you tested it. After review, merge using the repository convention and tag a release when a stable version needs a name.', language: 'text', code: 'Pull request description\n\nWhat changed?\n- Added a contact page\n\nWhy?\n- Visitors need a clear way to get in touch\n\nHow was it tested?\n- Checked at desktop and mobile widths\n- Confirmed the form labels and links', exercise: 'Write a pull request description for a small interface change, including motivation and test notes.', question: 'What makes a pull request easier to review?', choices: ['A focused change with context and test notes', 'One huge commit with no description', 'Removing the commit history'], answer: 0, answerNote: 'Focus and context help reviewers understand and verify the proposed change.' }),
  lesson('react-development', 4, { title: 'Conditional UI, lists & keys', duration: '55 min', summary: 'Render different interface states and repeat components reliably.', explanation: 'React can choose what to render based on state and props. Conditional expressions are useful for clear alternatives such as a loading message, an empty message, or a list. To render a collection, map data to elements. Give each item a stable key that identifies it across insertions and reordering; an array index is not a reliable identity when the list can change.', language: 'jsx', code: 'function LessonList({ lessons }) {\n  if (lessons.length === 0) return <p>No lessons yet.</p>;\n  return <ul>\n    {lessons.map((lesson) => (\n      <li key={lesson.id}>{lesson.title}</li>\n    ))}\n  </ul>;\n}', exercise: 'Render an empty message or a list depending on the data, and add a stable key to every lesson row.', question: 'Why should a dynamic list use stable keys?', choices: ['They help React identify items between renders', 'They encrypt each row', 'They force alphabetical order'], answer: 0, answerNote: 'Stable keys let React match an item when a list changes.' }),
  lesson('react-development', 5, { title: 'Forms & accessible interaction', duration: '55 min', summary: 'Build controlled inputs with clear labels and predictable submission.', explanation: 'A controlled input takes its value from React state and updates that state in its change handler. This makes the displayed value explicit and lets the app validate or reset it consistently. Forms should still use semantic form elements, visible labels, and submit buttons so browser and assistive technology behavior remains useful. Handle submit once at the form level and prevent a full page reload only when the application is managing submission.', language: 'jsx', code: 'function NameForm() {\n  const [name, setName] = useState("");\n  function submit(event) {\n    event.preventDefault();\n    alert(`Hello, ${name.trim()}`);\n  }\n  return <form onSubmit={submit}>\n    <label htmlFor="name">Your name</label>\n    <input id="name" value={name}\n      onChange={(event) => setName(event.target.value)} />\n    <button type="submit">Continue</button>\n  </form>;\n}', exercise: 'Add a required, labeled email field and a helpful validation message when its value is incomplete.', question: 'In a controlled React input, where does the displayed value come from?', choices: ['React state', 'A placeholder only', 'A manual DOM mutation'], answer: 0, answerNote: 'The value prop reflects state, and an event handler updates that state.' }),
  lesson('react-development', 6, { title: 'Fetch data & compose an application', duration: '65 min', summary: 'Connect components to remote data with clear request states.', explanation: 'A component can coordinate with an API by starting a request when the relevant view is active, then representing loading, success, empty, and error states in the interface. Keep request logic and presentation easy to reason about; pass data and event handlers through component props rather than reaching into distant DOM nodes. Abort or ignore outdated requests when the view changes so stale results do not replace newer ones.', language: 'jsx', code: 'function ArticlePanel() {\n  const [status, setStatus] = useState("loading");\n  const [articles, setArticles] = useState([]);\n\n  useEffect(() => {\n    const controller = new AbortController();\n    fetch("/api/articles", { signal: controller.signal })\n      .then((response) => {\n        if (!response.ok) throw new Error("Request failed");\n        return response.json();\n      })\n      .then((items) => { setArticles(items); setStatus("success"); })\n      .catch((error) => {\n        if (error.name !== "AbortError") setStatus("error");\n      });\n    return () => controller.abort();\n  }, []);\n}', exercise: 'Create a data panel that shows loading, error, empty, and populated states without mixing API logic into unrelated UI.', question: 'Why abort or ignore an outdated request?', choices: ['To prevent stale data replacing current results', 'To make the server return JSON', 'To remove the need for a loading state'], answer: 0, answerNote: 'A stale request can finish late and overwrite the result for the current view.' }),
  lesson('apis-fetch', 4, { title: 'Query parameters & request options', duration: '45 min', summary: 'Build requests with user input without creating fragile URLs.', explanation: 'A query parameter is a key-value pair in a URL, often used for search terms, filters, or pagination. URLSearchParams encodes values safely and avoids manual string concatenation errors. Requests can also include headers to describe accepted formats or provide a short-lived access token when a service requires authentication. Never place private server credentials in browser code.', language: 'javascript', code: 'const url = new URL("https://example.test/api/articles");\nurl.searchParams.set("q", searchTerm);\nurl.searchParams.set("page", "1");\n\nconst response = await fetch(url, {\n  headers: { Accept: "application/json" },\n});\nif (!response.ok) throw new Error("Search failed");\nconst results = await response.json();', exercise: 'Build a URL with a search term containing spaces and ampersands using URLSearchParams.', question: 'Why use URLSearchParams instead of concatenating a query string?', choices: ['It encodes parameter values correctly', 'It hides the request from the browser', 'It automatically authenticates a user'], answer: 0, answerNote: 'URLSearchParams handles encoding and formatting of query values.' }),
  lesson('apis-fetch', 5, { title: 'CORS, credentials & rate limits', duration: '50 min', summary: 'Understand browser API boundaries and protect access.', explanation: 'CORS (Cross-Origin Resource Sharing) is a browser security mechanism. A server uses response headers to state which web origins may read its responses; frontend code cannot bypass a CORS restriction by changing fetch options. Rate limits restrict how often a client may call a service. Handle a 429 response with respectful retry behavior, and follow the API provider rules for caching, attribution, and credentials.', language: 'javascript', code: 'const response = await fetch(apiUrl);\nif (response.status === 429) {\n  showMessage("Too many requests. Try again shortly.");\n  return;\n}\nif (!response.ok) {\n  throw new Error(`Request failed with ${response.status}`);\n}', exercise: 'Add separate user feedback for an unavailable network and a 429 rate-limit response.', question: 'Can frontend JavaScript override a server CORS policy?', choices: ['Yes, with a special fetch flag', 'No, the API server must allow the origin', 'Only on mobile'], answer: 1, answerNote: 'The API response must permit the requesting origin through its CORS headers.' }),
  lesson('apis-fetch', 6, { title: 'Reliable requests & a complete data view', duration: '55 min', summary: 'Avoid stale responses and build a useful API-backed experience.', explanation: 'A reliable data view plans for slow, failed, empty, and repeated requests. AbortController can cancel a fetch when a search is replaced or a component no longer needs the result. Debouncing waits for a short pause in typing before requesting, which can reduce unnecessary calls. Always keep the interface responsive and let the person know when a result is current or still loading.', language: 'javascript', code: 'let controller;\nasync function searchArticles(query) {\n  controller?.abort();\n  controller = new AbortController();\n  const url = new URL("/api/articles", location.origin);\n  url.searchParams.set("q", query);\n  const response = await fetch(url, { signal: controller.signal });\n  if (!response.ok) throw new Error("Search unavailable");\n  return response.json();\n}', exercise: 'Create a search interface with encoded query parameters, loading feedback, empty results, errors, and cancellation of an older request.', question: 'What does AbortController help a fetch-based interface do?', choices: ['Cancel a request that is no longer needed', 'Make every response successful', 'Remove the need to validate data'], answer: 0, answerNote: 'An abort signal can cancel work that is stale or no longer needed.' }),
  lesson('website-deployment', 4, { title: 'Assets, paths & performance', duration: '40 min', summary: 'Ship only needed assets and make sure their URLs resolve.', explanation: 'A built site references generated files such as JavaScript bundles, stylesheets, fonts, and images. Relative and root-relative paths behave differently, especially when an app is hosted under a subpath. Large images and unused assets increase transfer time, so resize and compress images and remove files the interface no longer uses. Inspect the network panel after deployment to spot missing or oversized resources.', language: 'text', code: 'Release review\n[ ] Build output contains expected assets\n[ ] Image dimensions match display size\n[ ] No asset requests return 404\n[ ] Paths work at the production base URL\n[ ] Main content appears before optional decoration', exercise: 'Inspect the production preview network requests and fix one oversized or missing asset.', question: 'What is a likely result of an incorrect production asset path?', choices: ['The asset request returns 404', 'The route changes automatically', 'The image becomes more accessible'], answer: 0, answerNote: 'A path that does not match the deployed file location fails to load.' }),
  lesson('website-deployment', 5, { title: 'Single-page routes, domains & HTTPS', duration: '45 min', summary: 'Configure direct links and connect a secure public address.', explanation: 'Client-side routes render different views after the application loads, but a static host receives the URL first. A rewrite or fallback must serve the app entry point for application paths that are not real files. A custom domain uses DNS records to direct traffic to the host, and HTTPS certificates protect connections. After changing DNS or hosting settings, verify the exact public URLs, including nested course and lesson links.', language: 'text', code: 'Static app settings\nBuild command: npm run build\nPublish directory: dist\n\nSPA fallback\n/* /index.html 200\n\nPost-deploy checks\n- Open /courses directly\n- Open a nested lesson URL directly\n- Confirm the HTTPS lock and canonical domain', exercise: 'Configure a fallback for the router and test a deep lesson link in a fresh browser tab.', question: 'Why configure a route fallback on a static host?', choices: ['So direct app paths load the client router', 'So source TypeScript runs on the host', 'So the site no longer needs HTML'], answer: 0, answerNote: 'The fallback serves the app shell, then the router renders the requested view.' }),
  lesson('website-deployment', 6, { title: 'Launch, verify & maintain', duration: '45 min', summary: 'Make a release accessible, observable, and straightforward to update.', explanation: 'A release is a particular version of the application made available to visitors. Before announcing it, verify headings, page metadata, image alternatives, keyboard access, contrast, responsive behavior, and direct route loading on the deployed version. Keep a known-good build so a broken release can be rolled back. After launch, check host logs or monitoring for broken requests and keep dependencies maintained.', language: 'text', code: 'Release checklist\n[ ] Production build and preview pass\n[ ] Direct routes load after refresh\n[ ] Keyboard and mobile checks pass\n[ ] Metadata and alternative text are present\n[ ] No credentials appear in client files\n[ ] Previous release can be restored', exercise: 'Run the checklist against the deployed site and write down one follow-up improvement based on what you find.', question: 'Why keep a known-good previous release?', choices: ['It provides a rollback path if a release breaks', 'It prevents all future bugs', 'It replaces the need for testing'], answer: 0, answerNote: 'A known-good version lets you restore service while investigating a bad release.' }),
]

const expandedExplanations: Record<string, string> = {
  'html-fundamentals-1': 'HTML (HyperText Markup Language) is the language used to describe the structure and meaning of a web document. Browsers read HTML elements such as headings, paragraphs, and links, then build a document tree that other browser features can understand. HTML is not a programming language: it describes content rather than performing calculations or decisions.\n\nA document declaration tells the browser to use modern standards mode. The head contains information about the document, including its character encoding and title; the body contains the page content people see. Inside the body, main identifies the page’s central content. Choose an element because it describes the content, not because its default appearance looks convenient.',
  'html-fundamentals-2': 'A heading structure is the outline of a page. The h1 names the page’s main topic; h2 elements introduce major sections, and lower-level headings introduce sections within them. This hierarchy helps people scan a page and gives screen-reader users a navigable outline. Choose heading levels for structure, not to get a particular font size; CSS controls appearance.\n\nLandmarks are semantic regions that identify major areas of a page. header, nav, main, and footer give browsers and assistive technologies useful navigation points. Use one main landmark for the primary content, and give a navigation landmark an accessible name when a page has more than one. A section should have a heading that tells people what the section contains.',
  'html-fundamentals-3': 'Links and buttons may look similar, but their jobs differ. An anchor with an href takes a person to a destination; a button performs an action on the current page, such as submitting a form. Descriptive link text lets people understand a destination when links are read out of context. Images that communicate information need alternative text that conveys their purpose; decorative images should not create distracting duplicate announcements.\n\nA label gives a form control its accessible name. Connect a label to an input by setting the label’s for value to the input’s id. A placeholder is only a hint: it disappears as someone types and does not replace a persistent label. Choose appropriate input types, such as email, so browsers can offer useful keyboards and built-in validation.',
  'css-responsive-design-1': 'A CSS rule contains a selector, which chooses elements, and declarations, which set properties such as color or padding. A declaration is a property-value pair inside braces. Selectors can target an element type, a class, an id, or relationships between elements. Classes are usually the most reusable way to describe a component’s style.\n\nThe cascade is the browser’s method for deciding which competing declaration applies. It considers the rule’s origin and importance, selector specificity, and then source order when priorities tie. Specificity is not a score to maximize: highly specific selectors make later changes difficult. Prefer small, purposeful rules, and use browser developer tools to inspect which declaration won instead of adding overrides blindly.',
  'css-responsive-design-2': 'CSS layout controls how elements are sized and positioned in available space. Flexbox is a one-dimensional layout system: it distributes items along a main axis, with a cross axis perpendicular to it. It is useful when arranging a toolbar, navigation items, or a row of controls. Properties such as gap, align-items, and justify-content describe spacing and alignment without manually positioning each item.\n\nGrid is a two-dimensional layout system that manages rows and columns together. It is a good fit for a page structure or a collection of cards that should align across rows. In the example, auto-fit and minmax let the browser create as many columns as fit while keeping each column above a useful minimum width. Choose the layout based on the relationship between the content, rather than reaching for fixed widths first.',
  'css-responsive-design-3': 'Responsive design is the practice of making a page work well across changing screen sizes, zoom levels, and input methods. Start with content that can wrap and grow naturally; use flexible units and max-width constraints to keep lines readable. A media query applies styles when a condition, such as a narrow viewport or reduced-motion preference, is true.\n\nA breakpoint is a point where the layout needs to change, not a preset for a particular phone model. Add one when content becomes cramped, controls collide, or reading order becomes awkward. Test keyboard focus, zoom, and reduced-motion behavior as well as width. A page that merely shrinks to fit a narrow screen is not necessarily responsive if people can no longer read or operate it comfortably.',
  'javascript-fundamentals-1': 'JavaScript is a programming language that lets a page calculate values, respond to events, and update the interface. A value is a piece of data, such as the string "Ari", the number 2, or the Boolean true. A variable is a named binding to a value. Use const when you will not reassign the binding and let when reassignment is necessary; avoid var in new code because its older scoping rules are easier to misunderstand.\n\nPrimitive values include strings, numbers, booleans, null, and undefined. Arrays hold ordered collections, while objects group related properties under names. In the example, learner is an object and learner.name reads one of its properties. const prevents assigning a different object to learner, but it does not freeze the object itself. Clear names and predictable types reduce bugs as a project grows.',
  'javascript-fundamentals-2': 'A function is a reusable block of code that can receive inputs and return a result. Parameters name the inputs in the function definition; arguments are the values supplied when the function is called. A return statement sends a result back to the caller. A focused function should have a clear responsibility, such as filtering durations, so it can be tested and reused.\n\nArrays represent ordered lists. filter creates a new array containing the items that satisfy a condition; map creates a new array by transforming every item. A conditional lets code choose a path based on a Boolean expression. Prefer returning results instead of changing unrelated variables inside a function: predictable functions are easier to reason about. Before applying a transformation, consider the empty-list case and values that may not match the expected type.',
  'javascript-fundamentals-3': 'The Document Object Model (DOM) is the browser’s object representation of an HTML document. JavaScript can find DOM nodes with selectors, listen for events, and update the document in response. An event is a notification that something happened, such as a click or form submission. Register a listener on the control that owns the interaction and keep the update close to that action.\n\nquerySelector returns the first matching element, or null if none exists, so production code should account for missing elements. In this example, a click creates an li node, fills it with plain text, and appends it to a list. textContent treats the value as text; innerHTML parses a string as markup and can create cross-site scripting vulnerabilities when the string contains untrusted input. Prefer textContent unless there is a carefully sanitized reason to parse HTML.',
  'git-github-1': 'Git is a version control system: it records a history of changes so you can review, compare, and restore work. A repository is the project together with that history. The working tree is the files you are editing; the staging area is a selection of changes prepared for the next commit; commits are saved snapshots with a message and parent history.\n\n git init creates a repository in the current folder. git status explains what is modified, untracked, or staged. git add selects changes for the next snapshot, and git commit records the staged snapshot. A .gitignore tells Git which generated or local files should not be tracked. Review status and the staged diff before committing so unrelated changes do not accidentally enter the same snapshot.',
  'git-github-2': 'A branch is a movable name for a line of commits. Creating a feature branch gives a change its own place to develop while the default branch remains stable. Commits on that branch preserve the work in small reviewable snapshots. When work is ready, it can be merged into the shared branch, often through a pull request on a hosting service.\n\nA pull request is a collaboration workflow, not a special kind of Git commit: it presents a proposed change so teammates can discuss, test, and approve it before merging. If the default branch changes while your branch is in progress, Git may need to combine edits. A merge conflict means Git cannot choose between overlapping changes automatically; open the affected files, decide the intended result, test it, and commit the resolution.',
  'git-github-3': 'A remote is a named address for another copy of a repository, commonly one hosted on GitHub. A local commit does not automatically appear on that remote. git push sends local commits; git fetch downloads remote history without integrating it, and git pull fetches then integrates remote changes. Understanding this distinction helps avoid surprises when collaborating.\n\nA README explains what a project does and how to run it. A .gitignore keeps generated files and local configuration out of normal commits, but ignoring a file does not protect a credential that has already been committed. Treat exposed keys as compromised: revoke or rotate them at the provider, remove them from the project, and follow the provider’s guidance for cleaning repository history. Never store private credentials in frontend source.',
  'react-development-1': 'React is a JavaScript library for describing user interfaces as components. A component is a function that receives data and returns a description of what should appear on screen. React calls components as needed and updates the DOM when the rendered result changes. Components make repeated patterns easier to maintain, but they work best when each one has a clear responsibility.\n\nProps are the inputs passed from a parent component to a child. They let a reusable LessonCard display different titles and durations without embedding those values in its implementation. Treat props as read-only: a child should not change the values it receives. Use descriptive prop names, and choose semantic HTML elements inside a component so that the interface remains understandable to browsers and assistive technology.',
  'react-development-2': 'State is data that can change while a component is being used and should cause the interface to update. useState gives a component a current value and a setter function. Calling the setter schedules React to render again with the next value; it does not directly edit the page’s DOM. Use state for information such as a counter, selected tab, or open dialog.\n\nWhen the next value depends on the previous one, pass an updater function to the setter. This makes rapid updates reliable because React applies the update to the latest queued value. State arrays and objects should be treated as immutable: create a new array or object with the intended change rather than mutating the existing value. A state update is different from changing a DOM node manually; React remains the source of truth for rendered UI.',
  'react-development-3': 'An effect is a React mechanism for synchronizing a component with something outside React, such as a browser event subscription, a timer, or an external widget. Effects are not required for every calculation or state change. If a value can be derived from current props and state during rendering, calculate it there rather than storing a duplicate and synchronizing it with an effect.\n\nA controlled form field gets its value from React state and reports edits through an event handler. This makes validation, submission, and reset behavior explicit. Prevent the browser’s default form submission when the app should handle the action without a page reload, and associate each input with a visible label. When an effect creates a subscription or timer, return cleanup logic so it is removed when the component no longer needs it.',
  'apis-fetch-1': 'An API (Application Programming Interface) is a contract that lets one program request data or actions from another. A web API commonly exposes URLs called endpoints. A client sends an HTTP request with a method such as GET; the server returns a response with a status code, headers, and sometimes a JSON body. JSON is a text format for representing objects, arrays, strings, numbers, booleans, and null.\n\nfetch starts a network request and returns a Promise that fulfills with a Response when a response arrives. It does not reject just because the server returned a status such as 404 or 500, so check response.ok or response.status before parsing the body as successful data. Requests can also fail because of network conditions or browser security rules such as CORS. Keep private API credentials on a server; a key included in browser JavaScript is visible to visitors.',
  'apis-fetch-2': 'Asynchronous work takes time and can finish successfully or fail. A Promise represents a result that may be available later; async and await make Promise-based code easier to read, but they do not make the request immediate. While a request is pending, the interface should explain that it is loading instead of appearing frozen.\n\nModel the full lifecycle explicitly: loading, success with results, success with no results, and failure. Catch network or parsing errors and show a useful message without exposing sensitive internals. A retry action should start a new request and return the interface to its loading state. If users can trigger overlapping requests, consider how the interface should handle an older response arriving after a newer one.',
  'apis-fetch-3': 'Remote data is outside your control, so check that it has the shape your interface expects before using it. A field may be missing, null, or a different type than the API documentation suggests. Validate or safely handle optional fields, and provide a useful empty state when there are no records to show.\n\nWhen rendering an array in React, give each item a stable key based on its identity, such as an API id. Keys help React associate items across updates; array indexes can produce incorrect reuse if items are inserted, removed, or reordered. Render text as text rather than treating API strings as trusted HTML. Links from external data should also be validated and given clear labels before users follow them.',
  'website-deployment-1': 'A production build is the optimized set of files prepared for a host to serve to visitors. It differs from the development server, which adds tools for fast editing and diagnostics. The build command checks and bundles source files into an output directory; in this Vite project that directory is dist.\n\nA successful build is necessary but not sufficient for release. Preview the generated files using the production preview server, then test the same routes, assets, and interactions people will use after deployment. Look for missing files, broken direct links, console errors, and layout issues. Keep the source project and the build output conceptually separate: normally you publish the generated dist output, not the development server.',
  'website-deployment-2': 'Static hosting serves files such as HTML, CSS, and JavaScript without running an application server for each page request. A content delivery network can cache those files close to visitors. A deployment connects a tested build to a host and makes that output available at a URL.\n\nA single-page application uses client-side routing: after the first HTML page loads, JavaScript chooses what to render for paths such as /courses or /progress. If someone opens a nested path directly, the static host may look for a physical file at that path and return 404. Configure a fallback rewrite so unknown app routes serve index.html, then verify a nested route by entering its full URL in a fresh browser tab.',
  'website-deployment-3': 'A domain is the human-readable name people use to reach a site. DNS records connect that name to the hosting service. HTTPS encrypts traffic between a visitor and the site and helps confirm the connection is with the expected domain; use the host’s certificate setup rather than collecting or handling certificates yourself.\n\nA launch check is a deliberate review of the deployed version, not just the local source. Test direct route loading, page titles and descriptions, keyboard focus, reduced motion, mobile layout, and the main interactions. Check that no private credentials appear in built files, and make sure third-party images or fonts are permitted and available. Monitor issues after release and keep dependencies updated so a public site remains dependable.',
}

export const lessons: Lesson[] = lessonSeeds.map((item) => ({
  ...item,
  explanation: expandedExplanations[item.id] ?? item.explanation,
}))

export function getCourseLessons(courseSlug: string) {
  return lessons.filter((item) => item.courseSlug === courseSlug)
}
